public abstract class PQBase implements Builder {
    public enum SortO { ASCX, DESCX }
    public interface Part { Boolean isEmpty(); }
    public interface Crit { }
    public interface Builder {
        Builder orderBy(String f);
        Builder orderBy(String f, SortO s);
        Builder lim(Integer n);
    }
    public virtual class Cond implements Crit {
        private String text;
        public Cond(String t) { text = t; }
        public virtual override String toString() { return text; }
    }
    public virtual class Junction extends Cond {
        protected final List<Crit> conditions = new List<Crit>();
        public Junction() { super(''); }
        public Junction add(Crit c) { conditions.add(c); return this; }
        public void clear() { conditions.clear(); }
        public Boolean isEmpty() { return conditions.isEmpty(); }
        public virtual override String toString() { return conditions.size() + ' conds'; }
    }
    protected virtual List<Part> build() { return new List<Part>(); }
    public virtual String render() {
        String s = '';
        for (Part p : build()) {
            if (p.isEmpty()) { continue; }
            s += p.toString();
        }
        return s;
    }
    public static List<String> strs(Iterable<Object> items) {
        List<String> r = new List<String>();
        for (Object o : items) { r.add(String.valueOf(o)); }
        return r;
    }
}

