public virtual class PQSql extends PQBase implements Builder {
    public interface Builder extends PQBase.Builder {
        PQBase.Builder join(String t);
    }
    public class Args { public Integer n = 1; }
    public virtual class DriverBase {
        public virtual String run(Args a) { return 'base' + a.n; }
    }
    public interface IDrv { String go(Args a); }
    public Integer argsNum() { return 3; }
    protected final WhereClause whereClause = new WhereClause();
    private Integer l = 0;
    private String ord = '';
    public PQSql orderBy(Object e) { ord += '' + e; return this; }
    public PQSql orderBy(Object e, PQBase.SortO s) { ord += e + ':' + s; return this; }
    public PQSql lim(Integer n) { l = n; return this; }
    public PQSql join(String t) { return this; }
    public PQSql addCond(PQBase.Crit c) { whereClause.add(c); return this; }
    public PQSql wherex(PQBase.Crit c) { whereClause.clear(); whereClause.add(c); return this; }
    protected override List<PQBase.Part> build() { return new List<PQBase.Part>{ whereClause }; }
    public override String toString() { return 'ORD ' + ord + ' L' + l; }
    private class WhereClause extends Junction implements PQBase.Part {
        public override String toString() { return 'WHERE ' + super.toString(); }
    }
    public class JoinHelper {
        private final List<Object> elems = new List<Object>{ 1, 'b' };
        public override String toString() { return 'X ' + String.join(PQBase.strs(elems), ', '); }
    }
}

