public class PQIter {
    public class ObjIter implements Iterable<Object> {
        public Iterator<Object> iterator() { return new List<Object>{ new Account(Name='z') }.iterator(); }
    }
    public class SObjIter implements Iterable<SObject> {
        private final Iterable<SObject> src;
        public SObjIter(Iterable<SObject> s) { src = s; }
        public Iterator<SObject> iterator() { return src.iterator(); }
    }
    public static String castShape() {
        Iterable<Object> o = new ObjIter();
        try {
            SObjIter s = new SObjIter((Iterable<SObject>) o);
            Integer n = 0;
            for (SObject x : s) { n++; }
            return 'ok ' + n;
        } catch (Exception e) { return e.getTypeName() + ': ' + e.getMessage(); }
    }
}

classes.PQIter2:
public class PQIter2 {
    public class ObjIter implements Iterable<Object> {
        public Iterator<Object> iterator() { return new List<Object>{ 'x', 2 }.iterator(); }
    }
    public class AccIter implements Iterable<Account> {
        public Iterator<Account> iterator() { return new List<Account>{ new Account(Name='a') }.iterator(); }
    }
    public static String t(Object o, String target) {
        try {
            if (target == 'sobj') { Iterable<SObject> x = (Iterable<SObject>) o; return 'ok'; }
            if (target == 'str') { Iterable<String> x = (Iterable<String>) o; return 'ok'; }
            if (target == 'int') { Iterable<Integer> x = (Iterable<Integer>) o; return 'ok'; }
            if (target == 'con') { Iterable<Contact> x = (Iterable<Contact>) o; return 'ok'; }
            if (target == 'acc') { Iterable<Account> x = (Iterable<Account>) o; return 'ok'; }
            if (target == 'obj') { Iterable<Object> x = (Iterable<Object>) o; return 'ok'; }
        } catch (Exception e) { return e.getTypeName() + ':' + e.getMessage(); }
        return '?';
    }
    public static String goClass() {
        String r = '';
        for (String tg : new List<String>{'sobj','str','int','con','acc','obj'}) {
            r += tg + '=' + t(new ObjIter(), tg) + '/' + t(new AccIter(), tg) + ';';
        }
        return r;
    }
    public static String go() {
        String r = '';
        for (String tg : new List<String>{'sobj','str','int','con','acc','obj'}) {
            r += tg + '=' + t(new ObjIter(), tg) + ' | ' + t(new AccIter(), tg) + ' | ' + t(new List<Object>{1}, tg) + ' | ' + t(new List<Account>(), tg) + '\n';
        }
        return r;
    }
}

