public class PFHash {
    private class Req {
        private final String v;
        public Req(String v) { this.v = v; }
        public override Integer hashCode() { return super.hashCode(); }
        public Boolean equals(Object o) { return o instanceof Req && ((Req) o).v == v; }
    }
    public static String go() {
        Req a = new Req('x');
        Integer h1 = a.hashCode();
        Integer h2 = a.hashCode();
        Set<Object> s = new Set<Object>{ a };
        return 'h ' + (h1 == h2) + ' ' + s.size() + ' ' + (h1 == System.hashCode(a));
    }
}

